<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Archer</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;800&display=swap" rel="stylesheet">
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  html,body { width:100%; height:100%; overflow:hidden; background:#1b2a4a; }
  body { font-family:'Baloo 2',sans-serif; }
  #game { position:fixed; inset:0; display:block; cursor:crosshair; }
  .hud { position:fixed; top:18px; left:0; right:0; display:flex; justify-content:center; gap:18px; pointer-events:none; z-index:5; }
  .pill { background:rgba(20,28,55,.72); border:1px solid rgba(255,255,255,.18); color:#fff; padding:8px 20px; border-radius:999px; font-weight:800; font-size:20px; letter-spacing:.5px; backdrop-filter:blur(6px); box-shadow:0 4px 14px rgba(0,0,0,.35); }
  .pill b { color:#ffd166; }
  #lives { display:flex; gap:6px; align-items:center; }
  .heart { width:22px; height:22px; }
  #overlay { position:fixed; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; background:radial-gradient(ellipse at center, rgba(30,40,80,.82), rgba(10,15,35,.94)); z-index:10; transition:opacity .45s; }
  #overlay.hidden { opacity:0; pointer-events:none; }
  #overlay h1 { font-size:min(84px,12vw); color:#fff; text-shadow:0 6px 0 rgba(0,0,0,.3), 0 0 44px rgba(255,209,102,.35); letter-spacing:2px; line-height:1; }
  #overlay h1 span { color:#ffd166; }
  #overlay p { color:#cfd8ee; margin:18px 0 26px; font-size:20px; text-align:center; max-width:520px; padding:0 20px; }
  .btn { font-family:inherit; font-weight:800; font-size:24px; letter-spacing:1px; color:#26160a; background:linear-gradient(#ffe29a,#ffb347); border:none; border-radius:14px; padding:16px 46px; cursor:pointer; box-shadow:0 6px 0 #b06f1d, 0 12px 26px rgba(0,0,0,.45); transition:transform .12s, box-shadow .12s; }
  .btn:hover { transform:translateY(-2px) scale(1.03); box-shadow:0 8px 0 #b06f1d, 0 16px 30px rgba(0,0,0,.5); }
  .btn:active { transform:translateY(3px); box-shadow:0 2px 0 #b06f1d; }
  #finalScore { font-size:30px; color:#ffd166; margin-bottom:6px; font-weight:800; }
  #hint { position:fixed; bottom:18px; width:100%; text-align:center; color:rgba(255,255,255,.65); font-size:15px; letter-spacing:.4px; z-index:5; pointer-events:none; }
</style>
</head>
<body>
<canvas id="game"></canvas>
<div class="hud">
  <div class="pill">SCORE <b id="score">0</b></div>
  <div class="pill" id="lives"></div>
</div>
<div id="overlay">
  <h1>BALLOON<br><span>ARCHER</span></h1>
  <p id="subtitle">Mouse to aim &nbsp;·&nbsp; hold &amp; drag back to draw the bow &nbsp;·&nbsp; release to fire</p>
  <button class="btn" id="startBtn">START</button>
</div>
<div id="hint">Pop the balloons before they float away. Three escapes and you're out.</div>
